import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/docs-editor/images-resize.png",p=JSON.parse('{"title":"Add and edit images","description":"Upload, paste, drag, or link an image into a doc, then resize, copy, or delete it.","frontmatter":{"title":"Add and edit images","description":"Upload, paste, drag, or link an image into a doc, then resize, copy, or delete it.","type":"how-to"},"headers":[],"relativePath":"docs-editor/images.md","filePath":"docs-editor/images.md"}'),d={name:"docs-editor/images.md"};function n(l,e,s,h,c,m){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="add-and-edit-images" tabindex="-1">Add and edit images <a class="header-anchor" href="#add-and-edit-images" aria-label="Permalink to &quot;Add and edit images&quot;">​</a></h1><p>Add pictures to a doc and size them to fit your layout. Images sit in the line of text, like a large character.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access to the document.</li><li>Uploads: PNG, JPEG, GIF, or WebP, up to 10 MB each.</li><li>An image added by URL keeps loading from its original site. If that site removes it, it disappears from your doc.</li></ul></div><h2 id="upload-an-image" tabindex="-1">Upload an image <a class="header-anchor" href="#upload-an-image" aria-label="Permalink to &quot;Upload an image&quot;">​</a></h2><ol><li>Put the cursor where the image should go.</li><li>Click <strong>Insert image</strong> (picture icon) in the toolbar and select <strong>Upload from computer</strong>.</li><li>Choose the image file.</li></ol><p>The image appears at the cursor. A wide image is scaled down to fit between the margins.</p><h3 id="drag-or-paste-an-image" tabindex="-1">Drag or paste an image <a class="header-anchor" href="#drag-or-paste-an-image" aria-label="Permalink to &quot;Drag or paste an image&quot;">​</a></h3><ul><li>Drag an image file from your computer onto the page.</li><li>Copy an image or take a screenshot in another app, then press <code>⌘+V</code> / <code>Ctrl+V</code> in the doc.</li></ul><h2 id="add-an-image-by-url" tabindex="-1">Add an image by URL <a class="header-anchor" href="#add-an-image-by-url" aria-label="Permalink to &quot;Add an image by URL&quot;">​</a></h2><ol><li>Click <strong>Insert image</strong> and select <strong>By URL…</strong>.</li><li>Paste the image address. It must start with <code>http://</code> or <code>https://</code>.</li><li>Click <strong>Insert</strong>.</li></ol><p>If the image can&#39;t be loaded, the box stays open so you can fix the address.</p><h2 id="resize-an-image" tabindex="-1">Resize an image <a class="header-anchor" href="#resize-an-image" aria-label="Permalink to &quot;Resize an image&quot;">​</a></h2><ol><li>Click the image. Eight square handles appear around it.</li><li>Drag a corner handle to resize it and keep its proportions. Hold <code>Shift</code> while dragging to resize freely.</li><li>Drag a side handle to stretch only the width or the height.</li></ol><p>While you drag, a label shows the new width and height in pixels.</p><p><img src="'+r+'" alt="Selected image with eight handles and a size label during a corner drag"></p><h2 id="copy-cut-or-delete-an-image" tabindex="-1">Copy, cut, or delete an image <a class="header-anchor" href="#copy-cut-or-delete-an-image" aria-label="Permalink to &quot;Copy, cut, or delete an image&quot;">​</a></h2><ol><li>Click the image to select it.</li><li>Press <code>⌘+C</code> / <code>Ctrl+C</code> to copy, <code>⌘+X</code> / <code>Ctrl+X</code> to cut, or <code>Delete</code> / <code>Backspace</code> to remove it.</li></ol><p>Paste a copied image anywhere in the same or another doc. To replace an image, delete it and insert the new one.</p><h2 id="move-the-cursor-around-an-image" tabindex="-1">Move the cursor around an image <a class="header-anchor" href="#move-the-cursor-around-an-image" aria-label="Permalink to &quot;Move the cursor around an image&quot;">​</a></h2><p>With an image selected:</p><ul><li><code>Escape</code> deselects it and puts the cursor next to it.</li><li><code>←</code> puts the cursor just before the image, and <code>→</code> just after it.</li><li><code>↑</code> and <code>↓</code> move the cursor up or down a line.</li></ul><p>To move an image, cut it and paste it at the new spot.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>Tap ⋮ (<strong>More formatting options</strong>) at the right end of the toolbar and select <strong>Image</strong> under <strong>Insert</strong> to upload a photo. Adding an image by URL needs a computer.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>You can&#39;t crop or rotate an image in the editor, or wrap text around it.</li><li>Images can&#39;t be added to a header or footer from the toolbar.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/paste-from-other-apps.html">Paste from other apps</a> for what happens to images in pasted web content.</li><li><a href="/docs/docs-editor/page-layout.html">Page layout</a> to widen the space between margins.</li><li>Troubleshooting if you see <a href="/docs/start/troubleshooting.html#couldn-t-upload-the-image">&quot;Couldn&#39;t upload the image&quot;</a> or <a href="/docs/start/troubleshooting.html#image-url-must-start-with-http-or-https">&quot;Image URL must start with http:// or https://&quot;</a>.</li></ul>',28)])])}const u=a(d,[["render",n]]);export{p as __pageData,u as default};
